'use strict';
Kit.suite(({ok})=>{
 const t=T,P=t.P,G=t.G;Kit.begin('soldier',1);Kit.clear();Kit.world();
 P.troops={};P.wounded={};P.woundedGroups=[];P.comps={};
 ok(t.bandPayroll().total===0,'hero alone owes no wages');
 const mounted=Object.keys(t.ST).find(k=>t.ST[k].mounted),m=t.soldierPay(mounted),f=t.soldierPay('hum_foot'),R=t.BAND_PAY.mounted,raw0=4*f+3*m+2*R+2*t.BAND_PAY.companion;P.troops={hum_foot:3,[mounted]:2};
 P.comps={brann:{ap:5},elske:{ap:5}};t.compInit('brann');t.compInit('elske');
 const r=t.partyRoster(P),foot=r.groups.find(g=>g.type==='hum_foot'),horse=r.groups.find(g=>g.type===mounted);
 P.wounded={hum_foot:1,[mounted]:1};P.woundedGroups=[{id:foot.id,type:'hum_foot',count:1},{id:horse.id,type:mounted,count:1}];
 ok(t.partyUnitWage(t.partyGroup(foot.id,r))===4*f,'foot group includes fit and wounded soldier wages ('+f+'g each, tier 1)');
 ok(t.partyUnitWage(t.partyGroup(horse.id,r))===3*m+2*R,'mounted surcharge applies to fit riders; wounded retain base pay ('+m+'g each by tier '+t.ST[mounted].tier+')');
 ok(t.partyUnitWage(t.partyGroup('hero',r))===0&&t.partyUnitWage(t.partyGroup('comp_brann',r))===2,'hero and companion wages use their own rates');
 let w=t.bandPayroll();ok(w.raw===raw0&&w.total===Math.ceil(raw0),'combined daily bill is rounded up once ('+raw0+' → '+Math.ceil(raw0)+')');
 P.gold=50;t.bandWages();ok(P.gold===50-Math.ceil(raw0),'daily deduction matches displayed bill');
 P.comps.brann.party=t.asParty({kind:'companion',troops:['hum_foot','hum_foot'],x:P.x,y:P.y});
 const raw1=raw0+2*f;w=t.bandPayroll();ok(w.detached===2&&w.raw===raw1&&w.total===Math.ceil(raw1),'detached companion troops remain included without charging the companion twice');
 P.comps.elske.hurt=G.day+2;ok(t.partyUnitWage(t.partyGroup('comp_elske',r))===2,'wounded companions still receive their wage');
 G.char='roster';t.openChar();
 ok(t.panel.querySelector('.fb-army-wage')?.textContent==='Wages: '+Math.ceil(raw1)+'g / day','Army header shows the real total daily bill');
 const card=t.panel.querySelector('[data-army-group="'+horse.id+'"]');ok(card?.querySelector('.fb-unit-wage')?.textContent==='Wages: '+(3*m+2*R)+'g / day','roster card shows its group wage without rounding it separately');
 t.act('party-select',horse.id);const pane=t.panel.querySelector('.fb-unit-inspector');ok(pane.textContent.includes('Upkeep '+(3*m+2*R)+'g a day'),'the inspector gives the group\'s upkeep ('+(pane.textContent.match(/Upkeep [\d.]+g a day/)||[''])[0]+')');
 const condition=t.partyCondition();ok(condition.includes('Daily wages')&&condition.includes('2 soldiers in companion-led parties')&&condition.includes('rounded up once to '+Math.ceil(raw1)+'g / day'),'Condition explains the full bill and detached-party costs');
 P.gold=1;const morale=P.morale;t.bandWages();ok(P.gold===0&&P.morale===morale-6,'unpaid wage penalty retains existing behavior');
});
